package com.ecole.gestion_scolaire.transport.entity;
import jakarta.persistence.*; import java.time.*;
@Entity @Table(name="transport_vehicle") public class TransportVehicle { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) public Long id; public String code; @Column(name="registration_number") public String registrationNumber; public String brand; public String model; public Integer capacity; @Column(name="insurance_expiry") public LocalDate insuranceExpiry; @Column(name="technical_inspection_expiry") public LocalDate technicalInspectionExpiry; public String status; public String notes; @Column(name="created_at") public OffsetDateTime createdAt; @Column(name="updated_at") public OffsetDateTime updatedAt; @PrePersist void p(){var n=OffsetDateTime.now();createdAt=n;updatedAt=n;if(status==null)status="ACTIVE";} @PreUpdate void u(){updatedAt=OffsetDateTime.now();} }
